const D = { energy:.6, scale:1, speed:1, density:.55, sway:.5, hue:40, x:.5, y:.5, style:'herbal', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// VOYNICH FOLIO — a botanical folio from an undeciphered herbal: an impossible
// plant (root ball, curling stem, lobed leaves, a spiked seed-head) drawn in
// brown ink and faded blue-green wash, swaying gently, wrapped by lines of
// looping gallows-script that write themselves in around it. A soft light rakes
// the aged vellum; when the folio fills it turns and a new specimen, new script,
// begins. Aged herbal colour, monochrome sepia, a dark nocturne with luminous
// ink, or a cyan blueprint negative.
// -----------------------------------------------------------------------------

const wh = h => ((h % 360) + 360) % 360;
const style = P.style;
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4)));
const BH = Math.max(200, Math.round(BW * height / width));
const key = BW + 'x' + BH;
const eseed = (P.seed|0)*1009 + (S.folio||0)*151;
const fr = i => { const s = Math.sin(i*127.1 + eseed*0.907 + 9.3)*43758.5453; return s - Math.floor(s); };

function pal(){
  if (style==='sepia')     return { pB:52,pH:34,pS:22, iH:26,iS:40,iB:22, leaf:[30,30,40], wash:[34,26,50], neg:0, lt:[42,55,100] };
  if (style==='nocturne')  return { pB:24,pH:220,pS:34, iH:40,iS:24,iB:90, leaf:[150,45,80], wash:[200,45,60], neg:1, lt:[190,45,100] };
  if (style==='blueprint') return { pB:24,pH:210,pS:52, iH:190,iS:14,iB:92, leaf:[180,40,90], wash:[200,50,72], neg:1, lt:[196,50,100] };
  return { pB:50,pH:wh(P.hue-2),pS:24, iH:26,iS:46,iB:22, leaf:[128,42,46], wash:[190,38,54], neg:0, lt:[44,55,100] }; // herbal
}
const C = pal();

// ---- vellum ground ----------------------------------------------------------
if (!S.paper || S.pkey!==key || S.pstyle!==style || S.pseed!==(P.seed|0)){
  S.pkey=key; S.pstyle=style; S.pseed=(P.seed|0);
  const pg=createGraphics(BW,BH); pg.colorMode(HSB,360,100,100,100); pg.noStroke();
  pg.background(C.pH,C.pS,C.pB);
  pg.blendMode(C.neg?ADD:MULTIPLY);
  for (let i=0;i<90;i++){ pg.fill(C.pH,C.pS*0.7,C.neg?26+fr(i)*18:100-(8+fr(i)*15),9); pg.ellipse(fr(i*3+1)*BW,fr(i*5+2)*BH,BW*(0.1+fr(i*7)*0.32),BW*(0.1+fr(i*7)*0.28)); }
  pg.blendMode(BLEND);
  for (let i=0;i<26;i++){ pg.fill(C.neg?200:28,C.neg?30:44,C.neg?34:40,7+fr(i*3)*11); pg.ellipse(fr(i*11+40)*BW,fr(i*13+41)*BH,BW*(0.03+fr(i*9)*0.09),BW*(0.03+fr(i*9)*0.09)); }
  for (let i=0;i<2600;i++){ pg.fill(C.pH,C.pS,C.neg?C.pB+fr(i)*22:C.pB-fr(i)*20,5); pg.rect(fr(i*2.1+700)*BW,fr(i*3.7+701)*BH,1.2,1.2); }
  S.paper=pg;
  const vg=createGraphics(BW,BH); vg.colorMode(HSB,360,100,100,100); vg.clear();
  const gc=vg.drawingContext; const rg=gc.createRadialGradient(BW/2,BH/2,BH*0.24,BW/2,BH/2,BH*0.82);
  rg.addColorStop(0,'rgba(0,0,0,0)'); rg.addColorStop(0.6,'rgba(0,0,0,0.10)'); rg.addColorStop(1,'rgba(0,0,0,0.46)');
  gc.fillStyle=rg; gc.fillRect(0,0,BW,BH); S.vig=vg;
}

// ---- plant + text structure -------------------------------------------------
const dens=P.density;
const pcx=BW*0.5, pRootY=BH*0.86, pTopY=BH*0.16;
const pRx=BW*0.20*(0.7+P.scale*0.4), pRy=(pRootY-pTopY)*0.5;
const lineH=BH*(0.050-dens*0.012);
const xh=lineH*0.5;
const nLines=Math.max(8,Math.floor((BH*0.78)/lineH));
if (!S.plant || S.gkey!==key || S.gstyle!==style || S.gfolio!==(S.folio||0) || S.gseed!==(P.seed|0) || S.gdens!==Math.round(dens*20) || S.gscale!==Math.round(P.scale*20)){
  S.gkey=key; S.gstyle=style; S.gfolio=(S.folio||0); S.gseed=(P.seed|0); S.gdens=Math.round(dens*20); S.gscale=Math.round(P.scale*20);
  // stem control points
  const stem=[]; const segs=7;
  for (let i=0;i<=segs;i++){ const f=i/segs; stem.push({ x:pcx+Math.sin(f*4+fr(2)*6)*BW*0.06*(1-f*0.4), y:pRootY-f*(pRootY-pTopY), f }); }
  // leaves along stem
  const leaves=[]; const nLv=3+Math.floor(fr(5)*4);
  for (let i=0;i<nLv;i++){ const f=0.25+i/(nLv)*0.6; const idx=Math.min(stem.length-1,Math.round(f*segs)); leaves.push({ f, side:i%2?1:-1, len:BW*(0.11+fr(i*7+3)*0.09), lobe:2+Math.floor(fr(i*5+4)*3), ph:fr(i*9+6)*6.28 }); }
  // roots
  const roots=[]; const nR=6+Math.floor(fr(8)*6);
  for (let i=0;i<nR;i++) roots.push({ a:Math.PI*(0.15+fr(i*3+9)*0.7), len:BW*(0.05+fr(i*5+10)*0.09), curl:(fr(i*7+11)-0.5)*2 });
  // seed-head type
  S.head = { type: Math.floor(fr(12)*3), n:6+Math.floor(fr(13)*8), r:BW*(0.05+fr(14)*0.05) };
  S.stem=stem; S.leaves=leaves; S.roots=roots;
  // text lines (skip strokes inside plant ellipse)
  const lines=[];
  for (let li=0; li<nLines; li++){
    const yb=BH*0.12+xh+li*lineH; if (yb>BH*0.9) break;
    const words=[]; let x=BW*0.10; const rightX=BW*0.90; const cw=xh*0.9;
    while (x<rightX-cw*2){
      const wl=2+Math.floor(fr(li*13+words.length*3+4)*6);
      const chars=[];
      for (let c=0;c<wl;c++){ const gall=fr(li*17+x+c)>0.78; chars.push({x, gall, kind:Math.floor(fr(li*7+x+c*3)*3)}); x+=cw*(gall?1.1:0.8); }
      words.push(chars); x+=cw*0.9;
    }
    lines.push({yb, words, cw});
  }
  S.txtL=lines; S.prog=0; S.phase='write'; S.dwell=0; S.fade=100;
  const ig=createGraphics(BW,BH); ig.colorMode(HSB,360,100,100,100); ig.clear(); S.ink=ig; S.drawn=0;
  S.plant=1;
}

// draw a line of gallows-script into ink buffer, skipping the plant hole
function inkLine(g, ln){
  const dark=0.5+P.energy*0.6; g.noFill();
  for (const w of ln.words) for (const ch of w){
    const insidePlant = ((ch.x-pcx)*(ch.x-pcx))/(pRx*pRx) + ((ln.yb-(pTopY+pRootY)/2)*(ln.yb-(pTopY+pRootY)/2))/(pRy*pRy) < 1;
    if (insidePlant) continue;
    g.stroke(C.iH,C.iS,C.iB,Math.min(100,66+dark*34)); g.strokeWeight(ln.cw*0.16);
    if (ch.gall){ // tall looped gallows character
      g.line(ch.x, ln.yb, ch.x, ln.yb-xh*1.7);
      g.ellipse(ch.x+ln.cw*0.14, ln.yb-xh*1.5, ln.cw*0.34, ln.cw*0.34);   // loop
      g.line(ch.x-ln.cw*0.22, ln.yb-xh*1.2, ch.x+ln.cw*0.30, ln.yb-xh*1.2); // crossbar
    } else if (ch.kind===0){ g.ellipse(ch.x+ln.cw*0.2, ln.yb-xh*0.4, ln.cw*0.5, ln.cw*0.55); }  // o/e body
    else if (ch.kind===1){ g.arc(ch.x+ln.cw*0.2, ln.yb-xh*0.4, ln.cw*0.5, ln.cw*0.7, Math.PI*0.1, Math.PI*1.2); } // c
    else { g.line(ch.x,ln.yb,ch.x,ln.yb-xh*0.9); g.arc(ch.x+ln.cw*0.15,ln.yb-xh*0.4,ln.cw*0.4,ln.cw*0.5,-0.4,2.6); } // i with tail
  }
}

// ---- advance ----------------------------------------------------------------
const total=S.txtL.length; const spd=0.35+P.speed*1.1;
if (S.phase==='write'){ S.prog+=(spd*2.0)/(K.fps||60); const upto=Math.min(total,Math.floor(S.prog)); while(S.drawn<upto){ inkLine(S.ink,S.txtL[S.drawn]); S.drawn++; } if (S.drawn>=total && S.prog>=total+1.5){ S.phase='dwell'; S.dwell=0; } }
else if (S.phase==='dwell'){ S.dwell+=1/(K.fps||60); if (S.dwell>2.6/(0.4+P.speed*0.8)) S.phase='fade'; }
else if (S.phase==='fade'){ S.fade-=120/(K.fps||60); if (S.fade<=0){ S.folio=(S.folio||0)+1; S.plant=null; S.txtL=null; } }

// ---- render -----------------------------------------------------------------
const t=K.t; const sxr=width/BW, syr=height/BH;
const dx=Math.sin(t*0.12)*width*0.005+Math.sin(t*0.30+1.1)*width*0.004, dy=Math.cos(t*0.10)*height*0.005;
const ox=(P.x-0.5)*width*0.12, oy=(P.y-0.5)*height*0.12;
const lpx=(Math.sin(t*0.17)*0.5+0.5)*0.6+(Math.sin(t*0.049+2)*0.5+0.5)*0.4;
const pageA=S.phase==='fade'?Math.max(0,S.fade):100;
const swayA=(0.5+P.sway)*0.05;
const sway=(Math.sin(t*0.37)*0.6+Math.sin(t*0.71+1.2)*0.3+Math.sin(t*1.13+0.4)*0.15)*swayA + A.lowmid*0.02;

push(); translate(dx+ox,dy+oy);
if (S.paper) image(S.paper,0,0,width,height);
if (S.ink){ push(); tint(0,0,100,pageA); image(S.ink,0,0,width,height); pop(); }

// ---- the plant (drawn live, sways) ----
if (S.plant!==null && S.stem){
  push(); translate(pcx*sxr, pRootY*syr); rotate(sway*0.5);   // rock about the base
  const iA=Math.min(100,(60+P.energy*40))*(pageA/100);
  // roots
  strokeCap(ROUND); noFill();
  for (const r of S.roots){ stroke(C.iH,C.iS*0.9,C.iB, iA*0.8); strokeWeight(Math.max(1,BW*0.006*sxr));
    const rx=Math.cos(r.a)*r.len, ry=Math.sin(r.a)*r.len*0.5;
    beginShape(); for(let s=0;s<=6;s++){ const f=s/6; vertex((rx*f + Math.sin(f*4+r.curl)*BW*0.02*f)*sxr, (ry*f)*syr + f*BW*0.05*syr); } endShape(); }
  // stem (relative to base at origin)
  stroke(C.iH,C.iS,C.iB,iA); strokeWeight(Math.max(1.4,BW*0.010*sxr)); noFill();
  beginShape();
  for (let i=0;i<S.stem.length;i++){ const p=S.stem[i]; const f=p.f; const bend=sway*f*f*BW*0.5;
    curveVertex((p.x-pcx+bend)*sxr, (p.y-pRootY)*syr); }
  endShape();
  // leaves
  for (const lv of S.leaves){ const idx=Math.min(S.stem.length-1,Math.round(lv.f*(S.stem.length-1))); const sp=S.stem[idx];
    const bend=sway*lv.f*lv.f*BW*0.5; const bx=(sp.x-pcx+bend), by=(sp.y-pRootY);
    const nod=Math.sin(t*0.9+lv.ph)*0.12*(0.5+P.sway);
    push(); translate(bx*sxr,by*syr); rotate(lv.side*(0.7)+nod);
    noStroke(); fill(C.leaf[0],C.leaf[1],C.leaf[2]*(0.7+0.4*Math.max(0,1-Math.abs((bx*sxr+width*0.5)/width-lpx)*3)), 62*(pageA/100));
    beginShape(); vertex(0,0);
    for (let s=0;s<=lv.lobe*2;s++){ const f=s/(lv.lobe*2); const wob=(s%2?1:0.5); curveVertex(lv.len*f*sxr, (Math.sin(f*Math.PI)*lv.len*0.4*wob)*syr*lv.side*-1 - lv.len*0.05*f*syr); }
    for (let s=lv.lobe*2;s>=0;s--){ const f=s/(lv.lobe*2); const wob=(s%2?0.5:1); curveVertex(lv.len*f*sxr, (Math.sin(f*Math.PI)*lv.len*0.4*wob)*syr*lv.side + lv.len*0.05*f*syr); }
    endShape(CLOSE);
    stroke(C.iH,C.iS,C.iB,iA*0.6); strokeWeight(Math.max(0.7,BW*0.004*sxr)); noFill(); line(0,0,lv.len*sxr,0);
    pop();
  }
  // seed-head at top
  const tp=S.stem[S.stem.length-1]; const bendT=sway*BW*0.5; const hx=(tp.x-pcx+bendT), hy=(tp.y-pRootY);
  push(); translate(hx*sxr,hy*syr);
  const hd=S.head; const cn=Math.max(0,1-Math.abs((hx*sxr+width*0.5)/width-lpx)*3);
  if (hd.type===0){ // spiked
    stroke(C.iH,C.iS,C.iB,iA); strokeWeight(Math.max(1,BW*0.005*sxr));
    for (let i=0;i<hd.n;i++){ const a=-Math.PI/2 + (i/hd.n-0.5)*Math.PI*1.2; line(0,0,Math.cos(a)*hd.r*sxr,Math.sin(a)*hd.r*syr); noFill(); }
    noStroke(); fill(C.wash[0],C.wash[1],C.wash[2]*(0.7+0.4*cn),60*(pageA/100)); ellipse(0,0,hd.r*0.6*sxr,hd.r*0.6*syr);
  } else if (hd.type===1){ // petal star
    noStroke();
    for (let i=0;i<hd.n;i++){ const a=(i/hd.n)*Math.PI*2; fill(C.wash[0],C.wash[1],C.wash[2]*(0.7+0.4*cn),55*(pageA/100)); push(); rotate(a); ellipse(hd.r*0.6*sxr,0,hd.r*0.8*sxr,hd.r*0.4*syr); pop(); }
    fill(C.leaf[0],C.leaf[1]*1.1,C.leaf[2],70*(pageA/100)); ellipse(0,0,hd.r*0.5*sxr,hd.r*0.5*syr);
  } else { // bulb cluster
    noStroke();
    for (let i=0;i<hd.n;i++){ const a=(i/hd.n)*Math.PI*2; const rr=hd.r*(0.5+fr(i*3+30)*0.5); fill(C.wash[0],C.wash[1],C.wash[2]*(0.7+0.4*cn),58*(pageA/100)); ellipse(Math.cos(a)*rr*0.6*sxr,Math.sin(a)*rr*0.4*syr,hd.r*0.5*sxr,hd.r*0.6*syr); }
  }
  pop();
  pop();
}
pop();

// raking light band
push(); blendMode(ADD); noStroke();
const glowA=(9+P.energy*12+A.rms*8)*(C.neg?0.7:1);
for (let b=0;b<5;b++){ fill(C.lt[0],C.lt[1]*(0.5+0.1*b),C.lt[2],glowA*(1-b/5)*0.42); rect(lpx*width-width*0.17,-height*0.05,width*0.34*(0.4+0.15*b),height*1.1); }
blendMode(BLEND); pop();

if (S.vig){ push(); blendMode(MULTIPLY); image(S.vig,dx+ox,dy+oy,width,height); blendMode(BLEND); pop(); }
if (P.alpha<100){ push(); noStroke(); fill(C.pH,C.pS,C.pB,100-Math.max(0,Math.min(100,P.alpha))); rect(0,0,width,height); pop(); }
blendMode(BLEND); noTint(); drawingContext.shadowBlur=0;
